<section class="panel expedicao-panel" data-tab-panel="recebimento" hidden>
    <div class="expedicao-heading"><div><h2>Confirmação de entrega</h2><p>Selecione uma entrega própria e registre quem recebeu o pedido.</p></div></div>
    <div class="expedicao-table-wrap"><table class="data-table expedicao-table entrega-table"><thead><tr><th>Pedido</th><th>Loja</th><th>Romaneio</th><th>Volumes</th><th>Expedido em</th><th>Status</th><th></th></tr></thead><tbody>
    <?php if (!empty($aguardandoRecebimento)): foreach ($aguardandoRecebimento as $item): $pedidoEntrega=$item['pedido']??[];$lojaEntrega=trim((string)($pedidoEntrega['cliente_nome_fantasia']??''))?:trim((string)($pedidoEntrega['cliente_razao_social']??''));$dataEntrega=!empty($item['data_expedicao'])?strtotime((string)$item['data_expedicao']):false;$entregaId=(int)$item['id']; ?>
        <tr><td><strong><?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?></strong></td><td><span class="entrega-loja"><?= $esc($lojaEntrega?:'Loja não identificada'); ?></span></td><td><?= $esc($item['romaneio']??'—'); ?></td><td><?= (int)($item['volumes']??1); ?></td><td><?php if($dataEntrega):?><span class="expedicao-date"><strong><?= date('Y-m-d',$dataEntrega); ?></strong><small><?= date('H:i:s',$dataEntrega); ?></small></span><?php else:?>—<?php endif;?></td><td><span class="entrega-status">Expedido</span></td><td><button type="button" class="button button-primary" data-open-delivery="<?= $entregaId; ?>" data-delivery-code="<?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?>">Entregar</button></td></tr>
    <?php endforeach; else: ?><tr><td colspan="7" class="expedicao-empty">Nenhuma entrega própria aguardando confirmação.</td></tr><?php endif; ?>
    </tbody></table></div>
</section>

<div class="entrega-modal" data-delivery-modal hidden><div class="entrega-modal__backdrop" data-close-delivery></div><section class="entrega-modal__dialog" role="dialog" aria-modal="true" aria-labelledby="delivery-modal-title"><header><div><h3 id="delivery-modal-title">Confirmar entrega</h3><p>Pedido <strong data-delivery-label></strong></p></div><button type="button" data-close-delivery aria-label="Fechar">×</button></header><form data-delivery-form><label>Nome do recebedor<input type="text" name="recebedor_nome" maxlength="120" autocomplete="name" required></label><label>Assinatura do recebedor<span class="entrega-signature"><canvas data-delivery-canvas></canvas><i></i><button type="button" class="button button-outline" data-clear-delivery>Limpar</button></span><input type="hidden" name="assinatura_recebedor"></label><footer><button type="button" class="button button-outline" data-close-delivery>Cancelar</button><button type="submit" class="button button-primary" data-delivery-submit disabled>Confirmar entrega</button></footer></form></section></div>

<style>
.entrega-table th,.entrega-table td{text-align:center!important;vertical-align:middle!important}.entrega-table th{font-size:10.6px!important}.entrega-table td{font-size:13px!important;white-space:nowrap}.entrega-table :is(th,td):nth-child(2){width:170px;max-width:170px}.entrega-loja{display:-webkit-box;height:32px;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-height:16px;white-space:normal;overflow-wrap:anywhere}.entrega-status{display:inline-flex;padding:6px 10px;border-radius:999px;background:#e0f2fe;color:#0369a1;font-size:12px;font-weight:850}.entrega-modal{position:fixed;z-index:12000;inset:0;display:grid;place-items:center;padding:16px}.entrega-modal[hidden]{display:none}.entrega-modal__backdrop{position:absolute;inset:0;background:rgba(15,23,42,.68);backdrop-filter:blur(4px)}.entrega-modal__dialog{position:relative;width:min(650px,100%);padding:27px;border-radius:24px;background:#fff;box-shadow:0 28px 80px rgba(15,23,42,.32)}.entrega-modal__dialog header{display:flex;justify-content:space-between;gap:16px;margin-bottom:20px}.entrega-modal__dialog h3{margin:0 0 4px}.entrega-modal__dialog p{margin:0;color:var(--text-muted)}.entrega-modal__dialog header button{width:36px;height:36px;border:0;border-radius:11px;background:var(--surface-muted);font-size:24px;cursor:pointer}.entrega-modal form{display:grid;gap:17px}.entrega-modal form label{display:grid;gap:8px;font-weight:800}.entrega-modal input[type=text]{width:100%;min-height:50px;padding:0 14px;border:1px solid var(--border);border-radius:13px;font:inherit}.entrega-signature{position:relative;display:block;height:220px;overflow:hidden;border:1px dashed color-mix(in srgb,var(--primary) 55%,var(--border));border-radius:15px;background:#fff}.entrega-signature.has-ink{border-color:var(--primary)}.entrega-signature canvas{position:absolute;z-index:2;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.entrega-signature i{position:absolute;z-index:1;left:9%;right:9%;bottom:28%;height:1px;background:#94a3b8}.entrega-signature>button{position:absolute;z-index:3;right:9px;top:9px}.entrega-modal footer{display:flex;justify-content:flex-end;gap:10px}@media(max-width:650px){.entrega-modal__dialog{padding:19px}.entrega-signature{height:190px}.entrega-modal footer{display:grid;grid-template-columns:1fr 1fr}}
</style>

<script>
(()=>{const modal=document.querySelector('[data-delivery-modal]'),form=modal?.querySelector('[data-delivery-form]'),canvas=form?.querySelector('[data-delivery-canvas]'),box=canvas?.closest('.entrega-signature'),hidden=form?.elements.assinatura_recebedor,name=form?.elements.recebedor_nome,submit=form?.querySelector('[data-delivery-submit]');if(!modal||!form||!canvas||!box||!hidden||!name||!submit)return;const ctx=canvas.getContext('2d');let drawing=false,ink=false;const resize=()=>{const rect=canvas.getBoundingClientRect();if(rect.width<2||rect.height<2)return false;const ratio=devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';return true};const update=()=>{submit.disabled=!(name.value.trim()&&hidden.value.startsWith('data:image/png;base64,'))};const clear=()=>{ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.restore();drawing=false;ink=false;hidden.value='';box.classList.remove('has-ink');update()};const persist=()=>{if(!ink)return;hidden.value=canvas.toDataURL('image/png');update()};const point=e=>{const rect=canvas.getBoundingClientRect();return{x:e.clientX-rect.left,y:e.clientY-rect.top}};canvas.addEventListener('pointerdown',e=>{e.preventDefault();if(canvas.width<2&&!resize())return;drawing=true;ink=true;box.classList.add('has-ink');const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();try{canvas.setPointerCapture(e.pointerId)}catch(error){}});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()});const finish=e=>{if(!drawing)return;drawing=false;persist();try{canvas.releasePointerCapture(e.pointerId)}catch(error){}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);window.addEventListener('pointerup',finish,true);name.addEventListener('input',update);form.querySelector('[data-clear-delivery]').addEventListener('click',clear);const close=()=>{modal.hidden=true;document.body.style.overflow='';form.reset();clear()};modal.querySelectorAll('[data-close-delivery]').forEach(button=>button.addEventListener('click',close));document.querySelectorAll('[data-open-delivery]').forEach(button=>button.addEventListener('click',()=>{form.action=`<?= $esc($url('expedicao/recebimento')); ?>/${encodeURIComponent(button.dataset.openDelivery)}`;modal.querySelector('[data-delivery-label]').textContent=button.dataset.deliveryCode||'';modal.hidden=false;document.body.style.overflow='hidden';requestAnimationFrame(()=>requestAnimationFrame(()=>{resize();clear();name.focus()}))}));form.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();persist();if(!name.value.trim()||!hidden.value){window.showAppToast?.('Informe o recebedor e faça a assinatura.','error');return}if(form.dataset.saving==='1')return;form.dataset.saving='1';submit.disabled=true;try{const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível confirmar a entrega.');if(data.confirmado!==true||data.assinatura_salva!==true||data.status!=='entregue')throw new Error('O servidor não confirmou a assinatura.');window.showAppToast?.('Entrega e assinatura salvas com sucesso.','success');setTimeout(()=>location.assign(`${location.pathname}?tab=concluidos`),350)}catch(error){window.showAppToast?.(error.message||'Não foi possível confirmar a entrega.','error');update()}finally{delete form.dataset.saving;update()}},true)})();
</script>
